"""populate_emd.py — Appends Early Modern (EMD) layer data to all CSV files."""
import csv, json, os

BASE = "/Users/shs/Documents/Claude/Projects/Knowlege Genealogy/04_nodes_edges"

def append_csv(filename, rows):
    fp = os.path.join(BASE, filename)
    with open(fp, 'a', newline='', encoding='utf-8') as f:
        csv.writer(f, quoting=csv.QUOTE_MINIMAL).writerows(rows)

